from lib import build
R = []
R.append((7177299,
("Sopa toscana de frijoles", "Esta sopa sustanciosa es una comida nutritiva que llena, y se adapta fácilmente para incluir sus verduras favoritas.", "4", "396 g",
 ["1 cucharadita de aceite de oliva", "1 cebolla, picada", "1 pimiento amarillo, picado", "1 zanahoria, en cubitos", "500 ml de caldo de verduras sin gluten y bajo en sal", "1 lata de 400 g de tomates picados", "2 hojas de repollo, picadas", "1 cucharadita colmada de orégano", "media cucharadita de tomillo", "1 lata de 400 g de frijoles borlotti, escurridos", "2 a 4 dientes de ajo, machacados", "2 cucharaditas de pesto", "pimienta negra, una lasca de queso y ramitas de albahaca fresca, para servir"],
 ["Ponga el aceite en una olla y agregue la cebolla, el pimiento y la zanahoria. Revuelva con frecuencia durante 5 minutos, hasta que empiecen a dorarse.", "Agregue el caldo, los tomates, el repollo, el orégano, el tomillo, los frijoles y el ajo. Deje que hierva, luego baje el fuego, tape y cocine a fuego lento durante 10 minutos.", "Sirva en platos hondos, ponga una cucharada de pesto en cada uno y espolvoree con abundante pimienta negra. Para servir, agregue una lasca de queso, si lo desea, y una ramita de albahaca fresca como adorno."],
 ["Como muchas recetas tradicionales, esta sopa suele prepararse con lo que se tenga a la mano. Puede agregar todo tipo de verduras, como calabaza, calabacitas o apio, o añadir otros frijoles, pasta e incluso carne, como jamón.", "Los frijoles borlotti son bajos en grasa, ricos en fibra dietética y una buena fuente de proteína y folato.", "Usar un queso de sabor fuerte, como parmesano, grana padano o cheddar, le permite usar menos cantidad y aun así disfrutar de un gran sabor.", "Instrucciones para congelar: Congele en porciones y descongele en el refrigerador, o descongele en el microondas revolviendo con frecuencia.", "Porciones de fruta/verdura por porción: 3"], []),
("حساء الفاصوليا التوسكاني", "حساء شهي ومشبع يشكّل وجبة مغذّية، ويمكن تعديله بسهولة ليشمل خضارك المفضلة.", "4", "396 غ",
 ["1 ملعقة صغيرة زيت زيتون", "1 بصلة، مفرومة", "1 فلفل رومي أصفر، مفروم", "1 جزرة، مقطعة إلى مكعبات", "500 مل مرق خضار خالٍ من الغلوتين وقليل الملح", "400 غ علبة طماطم مفرومة", "2 ورقة ملفوف، مفرومة", "1 ملعقة صغيرة مكوّمة أوريغانو", "نصف ملعقة صغيرة زعتر", "400 غ علبة فاصوليا بورلوتي، مصفّاة", "2–4 فصوص ثوم، مهروسة", "2 ملعقة صغيرة صلصة بيستو", "فلفل أسود وشرائح رقيقة من الجبن وأغصان ريحان طازج، للتقديم"],
 ["ضع الزيت في قدر وأضف البصل والفلفل والجزر. قلّب باستمرار لمدة 5 دقائق حتى يبدأ بالتحمّر.", "أضف المرق والطماطم والملفوف والأوريغانو والزعتر والفاصوليا والثوم. اتركه يغلي، ثم خفّض الحرارة وغطِّ القدر واتركه على نار هادئة لمدة 10 دقائق.", "اسكب الحساء في أوعية، وضع في كل وعاء ملعقة من البيستو، ورشّ كمية وفيرة من الفلفل الأسود. للتقديم، أضف شريحة رقيقة من الجبن إن رغبت، وغصن ريحان طازج للتزيين."],
 ["مثل كثير من الوصفات التقليدية، يُحضَّر هذا الحساء عادةً بما هو متوفر. يمكنك إضافة أنواع مختلفة من الخضار، مثل القرع أو الكوسا أو الكرفس، أو إضافة أنواع أخرى من الفاصوليا أو المعكرونة أو حتى اللحم، مثل لحم الخنزير المدخّن (الهام).", "فاصوليا بورلوتي قليلة الدهون، وغنية بالألياف الغذائية، ومصدر جيد للبروتين وحمض الفوليك.", "استخدام جبن قوي النكهة، مثل البارميزان أو غراندا بادانو أو الشيدر، يتيح لك استخدام كمية أقل منه في الطبخ مع الاستمتاع بنكهة رائعة.", "تعليمات التجميد: جمّده على شكل حصص ثم أذبه في الثلاجة، أو أذبه في الميكروويف مع التقليب باستمرار.", "حصص الفاكهة/الخضار لكل حصة: 3"], []),
))
R.append((7178593,
("Peras escalfadas rosadas", "Peras escalfadas en jarabe de grosella negra sin azúcar, con anís estrella y canela.", "4", "312 g",
 ["4 peras firmes, un poco verdes, peladas y con el rabito", "150 ml de jarabe de grosella negra sin azúcar", "500 a 600 ml de agua hirviendo (suficiente para cubrir las peras)", "2 estrellas de anís", "1 rama de canela"],
 ["Pele las peras y quíteles el corazón desde la base con un cuchillo pequeño o un pelador de verduras. Corte la base para que quede plana y las peras se sostengan de pie.", "Ponga las peras en una olla con el jarabe diluido en proporción 3:1, asegurándose de que queden totalmente sumergidas.", "Agregue el anís estrella y la rama de canela y deje que hierva. Baje el fuego y cocine a fuego lento de 20 a 30 minutos, hasta que las peras estén tiernas.", "Retire las peras de la olla y resérvelas. Hierva el líquido de 10 a 15 minutos, hasta que se reduzca a unos 200 ml, y luego retire el anís estrella y la rama de canela.", "Coloque las peras en un platón y rocíelas con la salsa. Sirva con una cucharada de yogur bajo en grasa o una alternativa sin lácteos."],
 ["Queda muy bien con manzanas en lugar de peras.", "Pruebe con otro jarabe, o agregue unas rodajas de jengibre fresco o 2 clavos de olor.", "Porciones de fruta/verdura por porción: 1"], []),
("كمثرى مسلوقة وردية", "كمثرى مسلوقة في شراب الكشمش الأسود الخالي من السكر مع اليانسون النجمي والقرفة.", "4", "312 غ",
 ["4 حبات كمثرى متماسكة وغير ناضجة تمامًا، مقشرة مع ترك العنق", "150 مل شراب الكشمش الأسود الخالي من السكر", "500-600 مل ماء مغلي (يكفي لتغطية الكمثرى)", "2 نجمة يانسون", "1 عود قرفة"],
 ["قشّر الكمثرى وأزل قلبها من القاعدة باستخدام سكين صغيرة أو مقشرة خضار. قصّ القاعدة لتصبح مسطحة حتى تقف الكمثرى منتصبة.", "ضع الكمثرى في قدر مع الشراب المخفف بنسبة 3:1، مع التأكد من غمرها بالكامل.", "أضف اليانسون النجمي وعود القرفة، ثم اتركه يغلي. خفّض الحرارة واتركه على نار هادئة لمدة 20-30 دقيقة حتى تصبح الكمثرى طرية.", "أخرج الكمثرى من القدر وضعها جانبًا. اغلِ السائل لمدة 10-15 دقيقة حتى يتبقى منه حوالي 200 مل، ثم أزل اليانسون النجمي وعود القرفة.", "ضع الكمثرى في طبق التقديم واسكب عليها الصلصة. قدّمها مع ملعقة من الزبادي قليل الدسم أو بديل خالٍ من الألبان."],
 ["تنجح الوصفة جيدًا مع التفاح بدلًا من الكمثرى.", "جرّب شرابًا مختلفًا أو أضف بضع شرائح من الزنجبيل الطازج أو 2 حبة قرنفل.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7179097,
("Pasanda de champiñones", "Este delicioso curri vegetariano combina una variedad de especias para crear una salsa sabrosa que va perfecta con los champiñones castaña. Esta receta fue seleccionada en colaboración con Slimming World.", "4", "646 g",
 ["Aceite en aerosol bajo en calorías", "1 cebolla, en rodajas finas", "4 dientes de ajo, machacados", "un trozo de 3 cm de jengibre fresco, pelado y rallado", "1 chile verde, picado fino, sin semillas si lo desea", "2 cucharaditas de semillas de comino", "1 cucharadita de semillas de cilantro", "½ cucharadita de fenogreco molido", "½ cucharadita de cúrcuma molida", "1 cucharadita de garam masala seco", "½ cucharadita de chile en polvo suave (opcional)", "400 g de tomates en lata", "400 ml de bebida de almendra natural sin azúcar", "1 kg de champiñones castaña, partidos por la mitad si son grandes", "Una pizca de hebras de azafrán, remojadas en 1 cucharada de agua hirviendo", "1 hoja de laurel seca", "1 rama de canela", "4 cucharadas de yogur natural sin grasa y sin azúcar, para servir", "20 g de hojas de cilantro fresco, para servir", "200 g de arroz basmati seco", "1 rama de canela", "4 vainas de cardamomo verde, machacadas", "3 clavos de olor", "Una pizca de hebras de azafrán"],
 ["Rocíe con aceite en aerosol bajo en calorías (un par de pulverizaciones) una sartén grande, honda y antiadherente, y colóquela a fuego medio. Fría la cebolla 5 minutos, hasta que se ablande. Agregue el ajo, el jengibre y el chile verde con un chorrito de agua y fría 3 minutos. Agregue las especias y un poco de agua y fría 2 minutos.", "Agregue a la sartén los tomates junto con la bebida de almendra y deje que todo llegue a hervir a fuego lento. Cocine a fuego suave de 8 a 10 minutos, o hasta que los tomates se deshagan, revolviendo con frecuencia.", "Ponga 200 g de arroz basmati seco en una olla antiadherente con tapa, con 1 rama de canela, las vainas de cardamomo, los clavos y el azafrán. Agregue agua suficiente para que cubra el arroz por la altura de una uña y colóquela a fuego medio-alto. Deje que hierva a fuego lento, cocine 1 minuto y tape. Baje el fuego al mínimo y, sin destapar, cocine 20 minutos, o hasta que se absorba todo el líquido.", "Pase la mezcla de tomate a una jarra medidora grande y licúela hasta obtener una salsa tersa con una licuadora de inmersión. Pasar la salsa a una jarra en lugar de dejarla en la sartén ayuda a que la licuadora la deje más tersa. (También puede usar una licuadora de jarra). Reserve.", "Rocíe con aceite en aerosol bajo en calorías (un par de pulverizaciones) una sartén grande y antiadherente, y colóquela a fuego medio-alto. Cuando esté caliente, agregue la mitad de los champiñones y fría de 5 a 6 minutos, revolviendo de vez en cuando, hasta que se doren intensamente. Páselos a un plato y repita con el resto de los champiñones.", "Regrese la salsa a la sartén. Agregue el azafrán, la hoja de laurel y la canela, y deje que hierva a fuego lento. Agregue los champiñones y cocine a fuego lento de 8 a 10 minutos, revolviendo con frecuencia. Sazone con pimienta. Divida en 4 platos hondos, retirando la hoja de laurel y la canela. Cubra con el yogur y el cilantro.", "Esponje el arroz con un tenedor para obtener un resultado perfecto, retirando la canela, las vainas de cardamomo y los clavos antes de servir."],
 ["Use arroz basmati integral para aumentar la fibra.", "Revise las mezclas de especias y condimentos para ver si tienen ingredientes agregados como azúcar, sal, harina o aceite. Si es posible, elija mezclas hechas solo de hierbas y especias.", "Puede usar el yogur natural que prefiera. Sin embargo, esto cambiará la información nutricional y la textura del platillo.", "Porciones de fruta/verdura por porción: 4"], []),
("باسندا الفطر", "كاري نباتي شهي يجمع مجموعة متنوعة من التوابل لصنع صلصة لذيذة تناسب فطر الكستناء تمامًا. اختيرت هذه الوصفة بالشراكة مع Slimming World.", "4", "646 غ",
 ["بخاخ طبخ منخفض السعرات", "1 بصلة، مقطعة إلى شرائح رفيعة", "4 فصوص ثوم، مهروسة", "قطعة زنجبيل طازج بطول 3 سم، مقشرة ومبشورة", "1 فلفل أخضر حار، مفروم ناعمًا، ومنزوع البذور إن رغبت", "2 ملعقة صغيرة بذور كمون", "1 ملعقة صغيرة بذور كزبرة", "½ ملعقة صغيرة حلبة مطحونة", "½ ملعقة صغيرة كركم مطحون", "1 ملعقة صغيرة غرام مسالا جافة", "½ ملعقة صغيرة مسحوق فلفل حار معتدل (اختياري)", "400 غ طماطم معلبة", "400 مل مشروب لوز سادة غير محلّى", "1 كغ فطر كستناء، مقطّع إلى نصفين إذا كان كبيرًا", "رشة خيوط زعفران، منقوعة في 1 ملعقة كبيرة ماء مغلي", "1 ورقة غار جافة", "1 عود قرفة", "4 ملعقة كبيرة زبادي طبيعي خالٍ من الدسم وغير محلّى، للتقديم", "20 غ أوراق كزبرة خضراء طازجة، للتقديم", "200 غ أرز بسمتي جاف", "1 عود قرفة", "4 حبات هيل أخضر مهروسة", "3 حبات قرنفل", "رشة خيوط زعفران"],
 ["رشّ مقلاة كبيرة عميقة غير لاصقة ببخّتين من بخاخ الطبخ منخفض السعرات وضعها على نار متوسطة. قلّب البصل لمدة 5 دقائق حتى يذبل. أضف الثوم والزنجبيل والفلفل الأخضر الحار مع قليل من الماء، ثم قلّب لمدة 3 دقائق. أضف التوابل وقليلًا من الماء وقلّب لمدة دقيقتين.", "أضف الطماطم مع مشروب اللوز إلى المقلاة واتركها حتى تغلي على نار هادئة. دعها تغلي بلطف لمدة 8-10 دقائق، أو حتى تتفتت الطماطم، مع التقليب باستمرار.", "ضع 200 غ من الأرز البسمتي الجاف في قدر غير لاصق بغطاء مع 1 عود قرفة وحبات الهيل والقرنفل والزعفران. اسكب ماءً يكفي ليعلو الأرز بمقدار ارتفاع ظفر، وضعه على نار متوسطة إلى عالية. اتركه يغلي بلطف، وغلِّه لمدة دقيقة واحدة ثم غطِّه. خفّض الحرارة إلى أدنى درجة، ومن دون رفع الغطاء اتركه يطهى لمدة 20 دقيقة، أو حتى يُمتص كل السائل.", "انقل خليط الطماطم إلى إبريق قياس كبير، ثم اخلطه حتى يصبح صلصة ناعمة باستخدام خلاط يدوي. نقل الصلصة إلى إبريق بدلًا من تركها في المقلاة يساعد الخلاط على جعلها أنعم. (يمكنك أيضًا استخدام خلاط كهربائي عادي). ضعها جانبًا.", "رشّ مقلاة كبيرة غير لاصقة ببخّتين من بخاخ الطبخ منخفض السعرات وضعها على نار متوسطة إلى عالية. عندما تسخن، أضف نصف كمية الفطر وقلّبه لمدة 5-6 دقائق مع التقليب من حين لآخر حتى يتحول إلى لون ذهبي داكن. انقله إلى طبق وكرّر العملية مع بقية الفطر.", "أعد الصلصة إلى المقلاة. أضف الزعفران وورقة الغار والقرفة، واتركها تغلي بلطف. أضف الفطر واتركه على نار هادئة لمدة 8-10 دقائق مع التقليب باستمرار. تبّل بالفلفل. وزّعه على 4 أوعية مع إزالة ورقة الغار والقرفة. ضع فوقه الزبادي والكزبرة.", "فلفِل الأرز بالشوكة للحصول على أفضل نتيجة، وأزل عود القرفة وحبات الهيل والقرنفل قبل التقديم."],
 ["استخدم أرز بسمتي بنيًّا لزيادة الألياف.", "تحقق من خلطات التوابل والبهارات بحثًا عن مكونات مضافة مثل السكر أو الملح أو الدقيق أو الزيت. اختر خلطات مصنوعة من الأعشاب والتوابل فقط إن أمكن.", "يمكنك استخدام الزبادي الطبيعي الذي تفضله. لكن ذلك سيغيّر المعلومات الغذائية وقوام الطبق.", "حصص الفاكهة/الخضار لكل حصة: 4"], []),
))
R.append((7181351,
("Coliflor al horno con frijoles negros y coco", "Estas deliciosas coliflores asadas, que equivalen a 2 de sus 5 porciones diarias de fruta y verdura, son aptas para veganos y muy sabrosas.", "4", "330 g",
 ["Jugo de 2 limones", "1 coliflor grande, cortada en 6 gajos del mismo tamaño", "2 cucharaditas de aceite de colza", "1 cucharada de semillas de mostaza negra", "un trozo de 2 pulgadas de jengibre fresco, pelado y picado fino", "2 dientes de ajo grandes, picados finos", "1 chile verde grande, sin semillas y picado fino", "1 pimiento rojo, sin corazón ni semillas, picado en trozos grandes", "2 cucharaditas de cúrcuma", "400 ml de leche de coco light", "400 g de frijoles negros de lata, escurridos y enjuagados", "Un puñado pequeño de cilantro fresco, picado en trozos grandes"],
 ["Precaliente el horno a 200 °C (180 °C con ventilador, gas 6). Hierva una olla grande de agua. Agregue el jugo de 1 limón. Escalde la coliflor 4 minutos. Escúrrala bien y reserve.", "Coloque a fuego bajo una charola grande para asar, resistente al calor. Agregue el aceite de colza y caliente suavemente. Agregue las semillas de mostaza negra y deje que chisporroteen de 40 a 50 segundos, hasta que revienten. Agregue el jengibre, el ajo, el chile, el pimiento rojo y la cúrcuma, y cocine 2 minutos, revolviendo constantemente. Vierta la leche de coco y deje que hierva. Acomode la coliflor en la charola y cúbrala con un poco de la salsa. Ase 20 minutos. Vuelva a bañar con la salsa, esparza los frijoles negros en la salsa y mezcle bien. Regrese al horno 5 minutos.", "Exprima encima el jugo de limón restante y esparza el cilantro antes de servir."],
 ["Porciones de fruta/verdura por porción: 2"], []),
("قرنبيط مشوي بالفاصوليا السوداء وجوز الهند", "هذا القرنبيط المحمّص اللذيذ، الذي يغطي 2 من حصصك الخمس اليومية من الفاكهة والخضار، مناسب للنباتيين وشهي جدًا.", "4", "330 غ",
 ["عصير 2 ليمونة", "1 قرنبيط كبير، مقطع إلى 6 أجزاء متساوية الحجم", "2 ملعقة صغيرة زيت اللفت (كانولا)", "1 ملعقة كبيرة بذور خردل أسود", "قطعة زنجبيل طازج بطول 2 بوصة، مقشرة ومفرومة ناعمًا", "2 فص ثوم كبير، مفروم ناعمًا", "1 فلفل أخضر حار كبير، منزوع البذور ومفروم ناعمًا", "1 فلفل رومي أحمر، منزوع القلب والبذور ومفروم فرمًا خشنًا", "2 ملعقة صغيرة كركم", "400 مل حليب جوز الهند الخفيف", "400 غ فاصوليا سوداء معلبة، مصفّاة ومشطوفة", "حفنة صغيرة من الكزبرة الخضراء الطازجة، مفرومة فرمًا خشنًا"],
 ["سخّن الفرن مسبقًا إلى 200° مئوية (180° مئوية للفرن بالمروحة، درجة الغاز 6). اغلِ قدرًا كبيرًا من الماء. أضف عصير ليمونة واحدة. اسلق القرنبيط لمدة 4 دقائق. صفّه جيدًا وضعه جانبًا.", "ضع صينية تحميص كبيرة مقاومة للحرارة على نار هادئة. أضف زيت اللفت وسخّنه بلطف. أضف بذور الخردل الأسود ودعها تطقطق لمدة 40-50 ثانية حتى تتفرقع. أضف الزنجبيل والثوم والفلفل الحار والفلفل الرومي الأحمر والكركم، وقلّب باستمرار لمدة دقيقتين. اسكب حليب جوز الهند واتركه يغلي. رتّب القرنبيط في الصينية واسكب فوقه بعض الصلصة. حمّصه لمدة 20 دقيقة. اسكب الصلصة فوقه مرة أخرى، وانثر الفاصوليا السوداء في الصلصة وحرّك جيدًا. أعده إلى الفرن لمدة 5 دقائق.", "اعصر فوقه عصير الليمون المتبقي وانثر الكزبرة قبل التقديم."],
 ["حصص الفاكهة/الخضار لكل حصة: 2"], []),
))
R.append((7183658,
("Espagueti a la boloñesa", "Con muchas verduras y lentejas, es una versión más saludable del platillo familiar favorito de siempre.", "6", "337 g",
 ["2 cucharaditas de aceite de colza", "2 cebollas medianas, picadas finas", "500 g de carne molida de res magra", "1 zanahoria, en cubitos finos", "1 pimiento amarillo, picado fino", "1 calabacita, en cubitos finos", "2 a 4 dientes de ajo, machacados", "1 cucharadita colmada de albahaca seca", "2 cucharaditas colmadas de orégano seco", "una pizca pequeña de hojuelas de chile", "1 cubito de caldo de res bajo en sal", "1 lata de 800 g de tomates picados", "1 cucharada de puré de tomate", "1 lata de 400 g de lentejas Puy, escurridas", "10 g de perejil recién picado", "400 g de espagueti integral", "un buen molido de pimienta negra", "6 hojas de albahaca fresca, desgarradas, para adornar"],
 ["Caliente el aceite en una olla y cocine suavemente las cebollas, revolviendo con frecuencia, hasta que empiecen a dorarse.", "Agregue la carne y cocine de 8 a 10 minutos, deshaciendo los grumos con una cuchara de madera.", "Agregue la zanahoria, el pimiento amarillo y la calabacita, y continúe cocinando suavemente 5 minutos más, siempre revolviendo con frecuencia.", "Agregue el ajo, las hierbas y las hojuelas de chile y revuelva 1 minuto. Agregue el cubito de caldo, seguido de los tomates y el puré de tomate.", "Deje que hierva a fuego lento, tape y cocine 15 minutos, revolviendo de vez en cuando y agregando un poco de agua si se evapora demasiado líquido y empieza a pegarse.", "Mientras tanto, cocine el espagueti según las instrucciones del paquete.", "Incorpore las lentejas y el perejil picado a la salsa y cocine 5 minutos.", "Agregue un molido de pimienta negra, espolvoree con albahaca y sirva con el espagueti integral.", "Espolvoree con lascas de parmesano, si lo desea, para servir."],
 ["Puede usar pavo molido o cerdo molido para esta salsa.", "Ideal para preparar en una tanda grande y congelar en porciones.", "Porciones de fruta/verdura por porción: 3"], []),
("سباغيتي بولونيز", "الكثير من الخضار والعدس يجعل هذه النسخة أكثر صحة من الطبق العائلي المحبوب.", "6", "337 غ",
 ["2 ملعقة صغيرة زيت اللفت (كانولا)", "2 بصلة متوسطة، مفرومة ناعمًا", "500 غ لحم بقري مفروم قليل الدهن", "1 جزرة، مقطعة إلى مكعبات صغيرة", "1 فلفل رومي أصفر، مفروم ناعمًا", "1 كوسا، مقطعة إلى مكعبات صغيرة", "2-4 فصوص ثوم، مهروسة", "1 ملعقة صغيرة مكوّمة ريحان مجفف", "2 ملعقة صغيرة مكوّمة أوريغانو مجفف", "رشة صغيرة من رقائق الفلفل الحار", "1 مكعب مرق لحم بقري قليل الملح", "800 غ علبة طماطم مفرومة", "1 ملعقة كبيرة معجون طماطم", "400 غ علبة عدس بوي، مصفّى", "10 غ بقدونس طازج مفروم", "400 غ سباغيتي من القمح الكامل", "كمية وفيرة من الفلفل الأسود المطحون", "6 أوراق ريحان طازجة ممزقة، للتزيين"],
 ["سخّن الزيت في قدر وقلّب البصل بلطف مع التحريك المستمر حتى يبدأ بالتحمّر.", "أضف اللحم واطهه لمدة 8-10 دقائق، مع تفتيت أي كتل من اللحم بملعقة خشبية.", "أضف الجزر والفلفل الرومي الأصفر والكوسا وتابع الطهي بلطف لمدة 5 دقائق أخرى، مع التحريك المستمر.", "أضف الثوم والأعشاب ورقائق الفلفل الحار وحرّك لمدة دقيقة. أضف مكعب المرق، ثم الطماطم ومعجون الطماطم.", "اتركه حتى يغلي بلطف، وغطِّه واطهه لمدة 15 دقيقة، مع التحريك من حين لآخر وإضافة قليل من الماء إذا تبخر السائل كثيرًا وبدأ يلتصق.", "في هذه الأثناء، اسلق السباغيتي حسب تعليمات العبوة.", "أضف العدس والبقدونس المفروم إلى الصلصة، ثم اتركها تطهى لمدة 5 دقائق.", "أضف قليلًا من الفلفل الأسود المطحون، ورشّ الريحان، وقدّمها مع السباغيتي من القمح الكامل.", "رشّ شرائح رقيقة من البارميزان إن رغبت، وقدّم."],
 ["يمكنك استخدام لحم الديك الرومي المفروم أو لحم الخنزير المفروم لهذه الصلصة.", "مثالية للطهي بكمية كبيرة ثم التجميد على شكل حصص.", "حصص الفاكهة/الخضار لكل حصة: 3"], []),
))
R.append((7185004,
("Curri de pollo y lentejas", "Una de nuestras recetas más populares; este curri es una excelente forma de aprovechar el pollo sobrante y los básicos de la despensa. También es ideal si tiene un presupuesto limitado.", "4", "271 g",
 ["1 cucharadita de semillas de comino molidas", "1 cucharadita de semillas de cilantro", "1 cucharada de aceite de colza", "2 cebollas, en rodajas finas", "4 dientes de ajo, en rodajas finas", "3 cm de jengibre fresco, picado fino", "1 a 3 chiles verdes, abiertos a lo largo", "400 g de muslo de pollo, cortado en trozos del tamaño de un bocado", "media cucharadita de chile en polvo", "1 cucharadita de garam masala", "1 cucharadita de cúrcuma en polvo", "jugo de 1 limón", "1 lata de 400 g de tomates picados", "150 g de lentejas rojas"],
 ["Ponga las semillas de comino y de cilantro en una olla seca y tuéstelas de 1 a 2 minutos. Agregue el aceite y las cebollas. Cocine 5 minutos, revolviendo con frecuencia, hasta que se doren.", "Agregue el ajo, el jengibre, los chiles verdes y los trozos de pollo, y cocine otros 2 a 3 minutos, revolviendo con frecuencia.", "Agregue el chile en polvo, el garam masala y la cúrcuma en polvo junto con el jugo de limón, los tomates y 500 ml de agua.", "Deje que hierva, mezcle bien, baje el fuego y cocine a fuego lento 15 minutos, revolviendo con frecuencia.", "Agregue las lentejas y cocine a fuego lento otros 15 minutos, revolviendo con frecuencia, hasta que estén cocidas."],
 ["Si no tiene a la mano todas las especias, puede usar su curri en polvo o en pasta favorito.", "Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador y recaliente hasta que esté muy caliente por completo.", "Porciones de fruta/verdura por porción: 3"], []),
("كاري الدجاج والعدس", "من أشهر وصفاتنا، وهذا الكاري طريقة رائعة لاستغلال بقايا الدجاج والمكونات الأساسية في خزانة المطبخ. وهو مثالي أيضًا إذا كانت ميزانيتك محدودة.", "4", "271 غ",
 ["1 ملعقة صغيرة بذور كمون مطحونة", "1 ملعقة صغيرة بذور كزبرة", "1 ملعقة كبيرة زيت اللفت (كانولا)", "2 بصلة، مقطعة إلى شرائح رفيعة", "4 فصوص ثوم، مقطعة إلى شرائح رفيعة", "3 سم زنجبيل طازج، مفروم ناعمًا", "1-3 فلفل أخضر حار، مشقوق", "400 غ فخذ دجاج، مقطع إلى قطع بحجم اللقمة", "نصف ملعقة صغيرة مسحوق فلفل حار", "1 ملعقة صغيرة غرام مسالا", "1 ملعقة صغيرة كركم مطحون", "عصير 1 ليمونة", "400 غ علبة طماطم مفرومة", "150 غ عدس أحمر"],
 ["ضع بذور الكمون والكزبرة في قدر جاف وحمّصها لمدة 1-2 دقيقة. أضف الزيت والبصل. اطهه لمدة 5 دقائق مع التقليب باستمرار حتى يتحمّر.", "أضف الثوم والزنجبيل والفلفل الأخضر الحار وقطع الدجاج، واطه لمدة 2-3 دقائق أخرى مع التقليب باستمرار.", "أضف مسحوق الفلفل الحار والغرام مسالا والكركم المطحون مع عصير الليمون والطماطم و500 مل من الماء.", "اتركه حتى يغلي، وحرّكه جيدًا، ثم خفّض الحرارة واتركه على نار هادئة لمدة 15 دقيقة مع التقليب باستمرار.", "أضف العدس واتركه على نار هادئة 15 دقيقة أخرى مع التقليب باستمرار، حتى ينضج."],
 ["إذا لم تتوفر لديك كل أنواع التوابل، يمكنك استخدام مسحوق الكاري أو معجونه المفضل لديك.", "تعليمات التجميد: يمكن تجميده بعد الطهي. أذبه في الثلاجة وأعد تسخينه حتى يصبح ساخنًا تمامًا من الداخل.", "حصص الفاكهة/الخضار لكل حصة: 3"], []),
))
R.append((7186194,
("Crema de espárragos", "Una sabrosa versión sin lácteos que usa leche de soya.", "2", "346 g",
 ["15 g de untable sin lácteos", "1 cebolla pequeña, picada fina", "10 puntas de espárrago, picadas", "25 g de harina de trigo todo uso", "450 ml de caldo de verduras reducido en sal", "150 ml de leche de soya sin azúcar", "pimienta negra recién molida"],
 ["Caliente el untable en una olla mediana, agregue la cebolla y los espárragos y fría de 2 a 3 minutos, hasta que todo empiece a ablandarse.", "Agregue la harina y cocine 1 minuto más.", "Poco a poco, incorpore el caldo, deje que hierva y cocine a fuego lento 10 minutos, hasta que los espárragos estén bien cocidos; reserve un par de puntas de espárrago para servir.", "Agregue la leche, caliente hasta casi el punto de ebullición, luego pase a una licuadora o procesador de alimentos y licúe hasta que quede tersa.", "Sazone con abundante pimienta negra y decore con las puntas de espárrago."],
 ["Sirva con pan crujiente o tostado.", "Porciones de fruta/verdura por porción: 1"], []),
("حساء الهليون الكريمي", "نسخة لذيذة خالية من الألبان تستخدم حليب الصويا.", "2", "346 غ",
 ["15 غ دهن نباتي خالٍ من الألبان", "1 بصلة صغيرة، مفرومة ناعمًا", "10 سيقان هليون، مقطعة", "25 غ دقيق عادي", "450 مل مرق خضار منخفض الملح", "150 مل حليب صويا غير محلّى", "فلفل أسود مطحون طازجًا"],
 ["سخّن الدهن النباتي في قدر متوسط، وأضف البصل والهليون وقلّبهما لمدة 2-3 دقائق حتى يبدأ كل شيء بالذبول.", "أضف الدقيق واطه لمدة دقيقة أخرى.", "أضف المرق تدريجيًا مع التحريك، واتركه يغلي ثم اتركه على نار هادئة لمدة 10 دقائق حتى ينضج الهليون تمامًا، واحتفظ ببضع سيقان هليون للتقديم.", "أضف الحليب وسخّنه حتى يقارب درجة الغليان، ثم ضعه في الخلاط أو محضّر الطعام واخلطه حتى يصبح ناعمًا.", "تبّل بكمية وفيرة من الفلفل الأسود وضع سيقان الهليون فوقه."],
 ["قدّمه مع خبز مقرمش أو توست.", "حصص الفاكهة/الخضار لكل حصة: 1"], []),
))
R.append((7190087,
("Nasi goreng con verduras en escabeche", "Pavo deshebrado con muchas verduras, huevo, cebollín y chile.", "6", "372 g",
 ["15 cm de pepino, en rodajas finas y luego picado", "1 cebolla morada, en rodajas finas", "1 zanahoria, cortada en listones con un pelador y luego en tiras", "jugo de media limón", "un tercio de cucharadita de edulcorante granulado", "2 cucharaditas de aceite de colza", "2 huevos, ligeramente batidos", "2 cebollas, en rodajas finas", "500 g de tiras de pavo para saltear", "1 pimiento rojo, en rodajas finas", "2 dientes de ajo, en rodajas", "1 chile rojo, picado", "160 g de repollo de Saboya, en tiras", "4 cebollines, picados", "1 cucharada colmada de pasta de nasi goreng", "160 g de chícharos congelados, descongelados", "480 g de arroz basmati cocido (240 g sin cocer)"],
 ["Mezcle todos los ingredientes del escabeche, tape y reserve, mezclando de vez en cuando.", "Ponga una cucharadita de aceite en una sartén antiadherente, agregue los huevos y cocine de 30 a 60 segundos para hacer un omelette delgado tipo crepa. Retírelo de la sartén, enróllelo y reserve.", "Agregue otra cucharadita de aceite a la sartén, agregue las cebollas en rodajas y cocine de 4 a 5 minutos, revolviendo con frecuencia. Agregue las tiras de pavo y el pimiento rojo, y cocine 4 minutos más.", "Agregue el ajo, el chile, el repollo y los cebollines, y cocine 3 minutos. Incorpore la pasta de nasi goreng y mezcle bien, agregando un chorrito de agua si empieza a pegarse.", "Incorpore el arroz cocido y revuelva con frecuencia de 4 a 5 minutos, hasta que esté muy caliente. Pase a un tazón para servir, cubra con el omelette en rodajas y sirva con las verduras en escabeche."],
 ["No guarde el arroz cocido en el refrigerador más de 24 horas. Enfríelo siempre por completo lo antes posible.", "Puede usar pollo o cerdo en lugar de pavo.", "La pasta de nasi goreng contiene camarón, por lo que no es vegetariana; para una opción vegetariana, sustitúyalo por tofu.", "Porciones de fruta/verdura por porción: 2"], []),
("ناسي غورينغ مع الخضار المخللة", "ديك رومي مقطّع شرائح مع الكثير من الخضار والبيض والبصل الأخضر والفلفل الحار.", "6", "372 غ",
 ["15 سم خيار، مقطع شرائح رفيعة ثم مفروم", "1 بصلة حمراء، مقطعة إلى شرائح رفيعة", "1 جزرة، مقطعة إلى شرائح طويلة بمقشرة الخضار، ثم إلى أشرطة", "عصير نصف ليمونة", "ثلث ملعقة صغيرة محلّي محبّب", "2 ملعقة صغيرة زيت اللفت (كانولا)", "2 بيضة، مخفوقة قليلًا", "2 بصلة مقطعة إلى شرائح رفيعة", "500 غ شرائح ديك رومي للقلي السريع", "1 فلفل رومي أحمر، مقطع إلى شرائح رفيعة", "2 فص ثوم مقطعة إلى شرائح", "1 فلفل أحمر حار، مفروم", "160 غ ملفوف سافوي، مقطع شرائح", "4 بصلات خضراء، مفرومة", "1 ملعقة كبيرة مكوّمة معجون ناسي غورينغ", "160 غ بازلاء مجمدة، مذابة", "480 غ أرز بسمتي مطبوخ (240 غ غير مطبوخ)"],
 ["اخلط جميع مكونات المخلل معًا، وغطِّها وضعها جانبًا مع التحريك من حين لآخر.", "ضع ملعقة صغيرة من الزيت في مقلاة غير لاصقة، ثم أضف البيض واطهه لمدة 30-60 ثانية لتحصل على أومليت رقيق يشبه الفطيرة. أخرجه من المقلاة ولفّه وضعه جانبًا.", "أضف ملعقة صغيرة أخرى من الزيت إلى المقلاة، وأضف البصل المقطع واطهه لمدة 4-5 دقائق مع التقليب باستمرار. أضف شرائح الديك الرومي والفلفل الرومي الأحمر، ثم اطهِ لمدة 4 دقائق أخرى.", "أضف الثوم والفلفل الحار والملفوف والبصل الأخضر، ثم اطهِ لمدة 3 دقائق. أضف معجون ناسي غورينغ وامزج جيدًا، مع إضافة رشة ماء إذا بدأ يلتصق.", "أضف الأرز المطبوخ وقلّب باستمرار لمدة 4-5 دقائق حتى يصبح ساخنًا جدًا. ضعه في وعاء التقديم، وزيّنه بشرائح الأومليت وقدّمه مع الخضار المخللة."],
 ["لا تحفظ الأرز المطبوخ في الثلاجة لأكثر من 24 ساعة. برّده تمامًا دائمًا في أقرب وقت ممكن.", "يمكنك استخدام الدجاج أو لحم الخنزير بدلًا من الديك الرومي.", "يحتوي معجون ناسي غورينغ على الروبيان، لذا فهو غير نباتي؛ استبدله بالتوفو للحصول على خيار نباتي.", "حصص الفاكهة/الخضار لكل حصة: 2"], []),
))
R.append((7194911,
("Pays de res y champiñones", "Estos pays de res y champiñones, cocidos a fuego lento y cubiertos con masa, acompañados de unas coles tiernas perfectamente cocidas al vapor, son ideales para una cena sabrosa. Esta receta fue seleccionada en colaboración con Slimming World.", "6", "597 g",
 ["1 cebolla, en rodajas finas", "3 tallos de apio, en rodajas finas", "300 g de champiñones castaña, en cuartos", "3 zanahorias, peladas y cortadas en rodajas de 2 cm", "3 a 4 ramitas de tomillo fresco", "3 dientes de ajo, machacados", "400 g de carne magra de res para guisar, sin grasa visible, en trozos de 2 cm", "2 latas de 400 g de frijoles cannellini, escurridos y enjuagados", "1 litro de caldo de res bajo en sal", "1 cucharada de salsa Worcestershire", "150 g de hojaldre reducido en grasa", "1 yema de huevo, batida", "500 g de coles tiernas, en tiras, para servir"],
 ["Precaliente el horno a 160 °C (140 °C con ventilador, gas 3). Ponga todos los ingredientes, excepto el hojaldre, la yema de huevo y las coles, en una cacerola grande resistente al fuego y sazone con pimienta. Deje que hierva a fuego lento en la estufa, luego tape y cocine en el horno 2 horas.", "Quite la tapa. Revuelva bien y regrese al horno, sin tapar, 1 hora y 30 minutos más, agregando los frijoles durante los últimos 20 minutos. Mientras tanto, corte del hojaldre 12 figuras de champiñón que no pesen más de 12.5 g cada una, o corte el hojaldre en 6 cuadros de 25 g. Forre una charola grande para hornear con papel para hornear y coloque encima las figuras de hojaldre. Barnice con la yema de huevo y refrigere hasta que las necesite.", "Saque la cacerola del horno, tape y colóquela a fuego muy bajo en la estufa para mantener caliente. Suba el horno a 220 °C (200 °C con ventilador, gas 7) y hornee el hojaldre de 20 a 25 minutos, hasta que se esponje y esté dorado. Cuando el hojaldre esté casi listo, cueza las coles al vapor de 2 a 3 minutos.", "Divida la mezcla de carne en 6 platos hondos, retirando las ramitas de tomillo, y luego reparta encima las figuras de hojaldre. Sirva con las coles."],
 ["La información nutricional incluye la sugerencia para servir.", "Porciones de fruta/verdura por porción: 3"], []),
("فطائر اللحم البقري والفطر", "فطائر اللحم البقري والفطر هذه، المطهوّة ببطء والمغطاة بالعجين والمقدّمة مع خضار الكرنب المطهوة على البخار بإتقان، مثالية لعشاء لذيذ. اختيرت هذه الوصفة بالشراكة مع Slimming World.", "6", "597 غ",
 ["1 بصلة، مقطعة إلى شرائح رفيعة", "3 سيقان كرفس، مقطعة إلى شرائح رفيعة", "300 غ فطر كستناء، مقطع أرباعًا", "3 جزرات، مقشرة ومقطعة إلى شرائح بسماكة 2 سم", "3-4 أغصان زعتر طازج", "3 فصوص ثوم، مهروسة", "400 غ لحم بقري قليل الدهن للطبخ، مع إزالة الدهن الظاهر، مقطع إلى قطع بحجم 2 سم", "2 علبة بحجم 400 غ من فاصوليا كانيليني، مصفّاة ومشطوفة", "1 لتر مرق لحم بقري قليل الملح", "1 ملعقة كبيرة صلصة ورسترشير", "150 غ عجينة ملفوفة (باف باستري) مخفضة الدسم", "1 صفار بيضة، مخفوق", "500 غ كرنب أخضر (سبرينغ غرينز)، مقطع شرائح، للتقديم"],
 ["سخّن الفرن مسبقًا إلى 160° مئوية (140° مئوية للفرن بالمروحة، درجة الغاز 3). ضع جميع المكونات، باستثناء العجينة وصفار البيض والكرنب، في طبق طهي كبير مقاوم للّهب وتبّل بالفلفل. اتركه حتى يغلي بلطف على الموقد، ثم غطِّه واطهه في الفرن لمدة ساعتين.", "أزل الغطاء. حرّك جيدًا وأعده إلى الفرن مكشوفًا لمدة ساعة ونصف أخرى، مع إضافة الفاصوليا في آخر 20 دقيقة. في هذه الأثناء، قصّ 12 شكل فطر من العجينة بحيث لا يزيد وزن كل منها عن 12.5 غ، أو قطّع العجينة إلى 6 مربعات وزن كل منها 25 غ. بطّن صينية خبز كبيرة بورق الخبز وضع أشكال العجين فوقها. افرشها بصفار البيض وبرّدها في الثلاجة حتى الحاجة.", "أخرج طبق الطهي من الفرن، وغطِّه وضعه على أخفض حرارة على الموقد ليبقى دافئًا. ارفع حرارة الفرن إلى 220° مئوية (200° مئوية للفرن بالمروحة، درجة الغاز 7) واخبز العجين لمدة 20-25 دقيقة حتى ينتفخ ويصبح ذهبي اللون. عندما تقارب العجينة على النضج، اطه الكرنب على البخار لمدة 2-3 دقائق.", "وزّع خليط اللحم على 6 أوعية مع إزالة أغصان الزعتر، ثم وزّع فوقه أشكال العجين. قدّمه مع الكرنب."],
 ["تشمل المعلومات الغذائية اقتراح التقديم.", "حصص الفاكهة/الخضار لكل حصة: 3"], []),
))
R.append((7195577,
("Trucha al vapor estilo chino", "Cocer al vapor es una forma saludable y tradicional de preparar pescado.", "2", "264 g",
 ["4 filetes de trucha arcoíris, limpios (unos 100 g cada uno)", "1 cucharada de aceite de ajonjolí", "1 cucharada de salsa de soya reducida en sodio", "ralladura y jugo de 1 limón", "2 dientes de ajo, en rodajas", "un trozo de 2.5 cm de jengibre, rallado", "1 manojo de cebollines, en rodajas"],
 ["Coloque una hoja de papel encerado en una vaporera grande y ponga encima el pescado.", "Mezcle el resto de los ingredientes y vierta con una cuchara sobre el pescado.", "Tape y cueza al vapor de 6 a 8 minutos, o hasta que el pescado esté cocido.", "Sirva con verduras salteadas, fideos o arroz."],
 ["Si no tiene vaporera, envuelva el pescado en papel para hornear y colóquelo sobre una rejilla encima de una charola para hornear. Agregue un poco de agua hirviendo a la charola y cubra con papel aluminio. Luego cocine en el horno a 200 °C (gas 6) de 8 a 10 minutos.", "Puede cocinar cualquier platillo con este método, pero si usa pescado entero o filetes gruesos tendrá que aumentar el tiempo de cocción.", "Porciones de fruta/verdura por porción: 0"], []),
("سمك السلمون المرقط المطهو على البخار على الطريقة الصينية", "الطهي على البخار طريقة صحية وتقليدية لطهي السمك.", "2", "264 غ",
 ["4 شرائح سلمون مرقط (ترواوت)، جاهزة (حوالي 100 غ لكل شريحة)", "1 ملعقة كبيرة زيت سمسم", "1 ملعقة كبيرة صلصة صويا قليلة الملح", "قشر مبشور وعصير 1 ليمونة خضراء", "2 فص ثوم، مقطعة إلى شرائح", "2.5 سم قطعة زنجبيل، مبشورة", "1 حزمة بصل أخضر، مقطعة إلى شرائح"],
 ["ضع ورقة ورق مقاوم للدهن في جهاز بخار كبير وضع السمك فوقها.", "اخلط جميع المكونات المتبقية معًا واسكبها بالملعقة فوق السمك.", "غطِّه بالغطاء واطهه على البخار لمدة 6-8 دقائق أو حتى ينضج السمك.", "قدّمه مع خضار مقلية سريعًا أو شعرية أو أرز."],
 ["إذا لم يتوفر لديك جهاز بخار، لفّ السمك بورق الخبز وضعه على رف سلكي فوق صينية خبز. أضف قليلًا من الماء المغلي إلى الصينية وغطِّها بورق الألمنيوم. ثم اطهه في الفرن على حرارة 200° مئوية (درجة الغاز 6) لمدة 8-10 دقائق.", "يمكنك طهي أي طبق بهذه الطريقة، ولكن إذا استخدمت سمكة كاملة أو شرائح سميكة فستحتاج إلى زيادة وقت الطهي.", "حصص الفاكهة/الخضار لكل حصة: 0"], []),
))
R.append((7197806,
("Mini panqueques de arándanos azules", "Comience el día con esta versión más saludable de un clásico desayuno estadounidense.", "10", "72 g",
 ["200 g de harina integral", "1 cucharadita de polvo para hornear", "1 huevo mediano, batido", "250 ml de leche descremada", "1 cucharadita de extracto de vainilla", "200 g de arándanos azules frescos", "2 cucharaditas de aceite de girasol", "1 cucharadita de azúcar refinada (opcional)"],
 ["Mezcle la harina y el polvo para hornear en un tazón.", "En otro tazón, bata juntos el huevo, la leche y el extracto de vainilla.", "Haga un hueco en el centro de la harina y luego incorpore poco a poco la mezcla de huevo y leche hasta obtener una masa tersa. Lo ideal es dejar reposar la masa unos minutos antes de cocinar.", "Aplaste ligeramente la mitad de los arándanos con un tenedor y mézclelos con la masa, junto con los arándanos restantes (enteros).", "Agregue un poco de aceite a una sartén antiadherente y luego vierta la masa en la sartén, 1 cucharada a la vez, para formar panqueques pequeños, cuidando que los arándanos queden distribuidos de manera uniforme.", "Cocine los panqueques a fuego medio de 2 a 3 minutos, luego voltee y cocine 2 minutos más. Los panqueques están listos para voltear cuando vea que aparecen burbujas en la superficie. Espolvoree con un poco de azúcar antes de servir, si la usa. Sirva con un poco de yogur sin azúcar o crema fresca sin azúcar, si lo desea."],
 ["Debería poder cocinar de 3 a 4 panqueques a la vez, según el tamaño de la sartén, pero conviene cocinar primero uno solo para comprobar que la sartén no esté demasiado caliente ni demasiado fría.", "Mantenga calientes los primeros panqueques colocándolos en un plato sobre una olla con agua a fuego lento.", "Instrucciones para congelar: Descongele durante 2 horas, o descongele y caliente en el microondas o en un horno moderado.", "Porciones de fruta/verdura por porción: 0"], []),
("فطائر البان كيك الصغيرة بالتوت الأزرق", "ابدأ يومك بهذه النسخة الأكثر صحة من الإفطار الأمريكي الكلاسيكي.", "10", "72 غ",
 ["200 غ دقيق القمح الكامل", "1 ملعقة صغيرة بيكنج باودر", "1 بيضة متوسطة، مخفوقة", "250 مل حليب خالي الدسم", "1 ملعقة صغيرة خلاصة الفانيليا", "200 غ توت أزرق طازج", "2 ملعقة صغيرة زيت دوار الشمس", "1 ملعقة صغيرة سكر ناعم (اختياري)"],
 ["اخلط الدقيق والبيكنج باودر في وعاء.", "في وعاء آخر، اخفق البيض والحليب وخلاصة الفانيليا معًا.", "اصنع حفرة في وسط الدقيق، ثم أضف خليط البيض والحليب تدريجيًا مع التحريك حتى تحصل على عجينة سائلة ناعمة. من الأفضل ترك العجينة ترتاح بضع دقائق قبل الطهي.", "اهرس نصف كمية التوت الأزرق قليلًا بالشوكة وأضفه إلى العجينة مع بقية التوت (الكامل).", "ضع قليلًا من الزيت في مقلاة غير لاصقة، ثم اسكب العجينة في المقلاة، ملعقة كبيرة واحدة في كل مرة، لتشكيل فطائر صغيرة، مع التأكد من توزيع التوت بالتساوي.", "اطه الفطائر على حرارة متوسطة لمدة 2-3 دقائق، ثم اقلبها واطهها لمدة دقيقتين أخريين. تكون الفطائر جاهزة للقلب عندما تلاحظ ظهور فقاعات على سطحها. رشّ قليلًا من السكر قبل التقديم إن رغبت. قدّمها مع قليل من الزبادي غير المحلّى أو الكريمة الطازجة غير المحلّاة، إن رغبت."],
 ["يمكنك طهي 3-4 فطائر في المرة الواحدة حسب حجم المقلاة، ولكن من الجيد أن تطهو فطيرة واحدة أولًا للتأكد من أن المقلاة ليست ساخنة جدًا ولا باردة جدًا.", "أبقِ الدفعة الأولى من الفطائر دافئة بوضعها في طبق فوق قدر من الماء على نار هادئة.", "تعليمات التجميد: أذبها لمدة ساعتين، أو أذبها وسخّنها في الميكروويف أو في فرن معتدل الحرارة.", "حصص الفاكهة/الخضار لكل حصة: 0"], []),
))
R.append((7199003,
("Pastel de chocolate, almendra y frutos rojos", "Un excelente centro de mesa para su merienda.", "8", "113 g",
 ["1 cucharadita de aceite de colza (para el molde)", "50 g de harina integral", "50 g de harina de trigo todo uso", "15 g de fécula de maíz", "1 cucharadita de polvo para hornear", "15 g de cacao en polvo", "4 huevos medianos, separados", "1 cucharada de yogur griego sin grasa (0 %)", "4 cucharadas de edulcorante granulado", "2 cucharaditas de extracto natural de almendra", "200 g de quark sin grasa (queso crema)", "1 cucharada de edulcorante granulado", "175 g de fresas frescas, en rodajas", "125 g de frambuesas frescas"],
 ["Caliente el horno a 190 °C (gas 5) y engrase ligeramente con aceite un molde para pastel de 20 cm.", "Cierna la harina integral, la harina todo uso, la fécula de maíz, el polvo para hornear y el cacao en polvo en un tazón. (El salvado de la harina integral no pasará por el colador; simplemente agréguelo de nuevo al tazón).", "En otro tazón, ponga las yemas, el yogur, el edulcorante y el extracto de almendra y bata bien.", "En un tazón aparte, bata las claras a punto de nieve firme.", "Incorpore poco a poco los ingredientes secos y la mezcla de yemas y yogur con movimientos envolventes, y luego incorpore con cuidado las claras.", "Vierta de inmediato la mezcla en el molde engrasado y hornee de 20 a 25 minutos; luego saque del horno y deje enfriar sobre una rejilla.", "Mientras tanto, prepare la cobertura agregando 1 cucharada de edulcorante al quark y mezclando bien; déjela en el refrigerador hasta que esté lista para cubrir el pastel.", "Cuando el pastel esté frío, cúbralo con el quark endulzado y decore con fresas y frambuesas frescas."],
 ["Las claras batidas hacen el pastel más ligero, así que cuide de no mezclar de más, porque el pastel podría quedar un poco pesado (¡pero igual sabrá bien!).", "Cuando regrese las claras a la mezcla del pastel, incorpórelas con suavidad para conservar las burbujas de aire.", "Asegúrese de que el pastel esté completamente frío antes de agregar la cobertura.", "Cualquier fruta de verano queda bien. Pruebe a agregar arándanos azules, o use rodajas de durazno o chabacano frescos."], []),
("كعكة الشوكولاتة واللوز والتوت", "قطعة مركزية رائعة لطاولة شاي بعد الظهر.", "8", "113 غ",
 ["1 ملعقة صغيرة زيت اللفت (كانولا) (لقالب الكعك)", "50 غ دقيق القمح الكامل", "50 غ دقيق عادي", "15 غ نشا الذرة", "1 ملعقة صغيرة بيكنج باودر", "15 غ مسحوق كاكاو", "4 بيضات متوسطة، مفصولة", "1 ملعقة كبيرة زبادي يوناني خالٍ من الدسم (0%)", "4 ملعقة كبيرة محلّي محبّب", "2 ملعقة صغيرة خلاصة لوز طبيعية", "200 غ كوارك خالٍ من الدسم (جبن كريمي)", "1 ملعقة كبيرة محلّي محبّب", "175 غ فراولة طازجة، مقطعة إلى شرائح", "125 غ توت العليق الطازج"],
 ["سخّن الفرن إلى 190° مئوية (درجة الغاز 5) ودهّن قالب كعك قطره 20 سم بقليل من الزيت.", "اغربل دقيق القمح الكامل والدقيق العادي ونشا الذرة والبيكنج باودر ومسحوق الكاكاو في وعاء. (نخالة دقيق القمح الكامل لن تمر من المنخل، فأضفها مرة أخرى إلى الوعاء).", "في وعاء آخر، ضع صفار البيض والزبادي والمحلّي وخلاصة اللوز واخفقها جيدًا.", "في وعاء منفصل، اخفق بياض البيض حتى يتكوّن ثلج متماسك.", "اخلط المكونات الجافة وخليط صفار البيض والزبادي معًا تدريجيًا بالطي، ثم اطوِ بياض البيض بحذر.", "ضع الخليط فورًا في قالب الكعك المدهون واخبزه لمدة 20-25 دقيقة، ثم أخرجه من الفرن واتركه يبرد على رف سلكي.", "في هذه الأثناء، حضّر الطبقة العلوية بتحريك ملعقة كبيرة واحدة من المحلّي في الكوارك وخلطها جيدًا، ثم ضعها في الثلاجة حتى تكون جاهزًا لتغطية الكعكة.", "عندما تبرد الكعكة، غطِّها بالكوارك المحلّى وزيّنها بالفراولة والتوت الطازج."],
 ["بياض البيض المخفوق يجعل الكعكة أخف، لذا احرص على عدم المبالغة في الخلط لأن الكعكة قد تصبح ثقيلة قليلًا (لكن مذاقها سيبقى جيدًا!).", "عند إعادة بياض البيض إلى خليط الكعكة، اطوِه برفق للحفاظ على فقاعات الهواء داخله.", "تأكد من أن الكعكة قد بردت تمامًا قبل إضافة الطبقة العلوية.", "تناسب أي فاكهة صيفية. جرّب إضافة التوت الأزرق، أو استخدم شرائح من الخوخ أو المشمش الطازج."], []),
))
build(1, R)
